/* Turn Around remains a native editable TiddlyWiki tiddler.
   The production's cinematic stylesheet widens the story river to the
   viewport and hides the titlebar. Restore TiddlyWiki navigation here,
   while keeping the separate opt-in fullscreen player unchanged. */
@media (min-width: 960px) {
  body.tc-body .tc-story-river {
    box-sizing: border-box;
    position: relative;
    left: 0 !important;
    width: auto !important;
    max-width: none !important;
    margin: 0 280px 0 24px !important;
    padding: 42px !important;
  }
  /* When the native sidebar is closed, reclaim its reserved space. */
  body.tc-body:not(:has(.tc-sidebar-scrollable)) .tc-story-river {
    margin-right: 0 !important;
    padding-right: 3em !important;
  }
}
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-titlebar,
.tc-tiddler-frame[data-tiddler-title="Turn Around"] .tc-tags-wrapper {
  display: block !important;
}
